-- ─── NEW YORK ───
('11111111-0000-0000-0000-000000000001', 'Diwali: South Asian Founders & VCs Mixer', 'A Diwali celebration for South Asian founders and the investors who back them. It is hosted by Oasis and Inception Capital. You get warm intros, sweets, and one of the friendliest rooms of the season.', 'Venue shared on registration', NULL, NULL, 'Founder & VC Mixers', '2026-11-10', '18:30', 'Free', 'https://www.garysguide.com/events/ohe8f5w/Diwali-South-Asian-Founders-VCs-Mixer', 2),
('11111111-0000-0000-0000-000000000001', 'Female Founders & Funders', 'An evening of drinks at Luminary for women building companies and the funders who write the cheques. The room stays small and intros happen fast. Bring a crisp one-line pitch.', 'Luminary', '1204 Broadway, 4th Fl', 'NoMad', 'Founder & VC Mixers', '2026-11-11', '17:00', '$20', 'https://www.garysguide.com/events/obqqetd/Female-Founders-Funders', 3),
('11111111-0000-0000-0000-000000000001', 'Startup Founders, Investors & Talent Mixer', 'A twice-monthly mixer on the 11th floor of an unmarked Lower East Side space. Founders, angels and early hires work the room together. The address is part of the appeal.', 'Unlisted', '3 Freeman Alley, 11th Fl', 'Lower East Side', 'Founder & VC Mixers', '2026-11-11', '18:00', NULL, 'https://www.garysguide.com/events/xpda3w2/Startup-Founders-Investors-Talent-Mixer', 2),
('11111111-0000-0000-0000-000000000001', 'Founder, Funder, Or Just Finder', 'An after-work mixer at the Hotel Seville that welcomes founders, investors and the curious. The bar sits in a beaux-arts lobby. Nobody asks which of the three you are until the second drink.', 'Hotel Seville', '22 E 29th St', 'NoMad', 'Founder & VC Mixers', '2026-11-19', '17:00', 'Free', 'https://www.garysguide.com/events/e0jgey6/Founder-Funder-Or-Just-Finder', 2),
('11111111-0000-0000-0000-000000000001', 'NYC B2B: AI Founders & Investors Meetup', 'A meetup for B2B AI founders and the seed and Series A investors who track them, held at The Ivory Peacock in NoMad. Expect plenty of agent talk and real pipeline conversations.', 'The Ivory Peacock', '38 W 26th St', 'NoMad', 'Founder & VC Mixers', '2026-11-24', '18:00', 'Free', 'https://www.garysguide.com/events/mw05mc5/NYC-B2B-AI-Founders-Investors-Meetup', 3),
('11111111-0000-0000-0000-000000000001', 'The Builder Series: Founder, Investor & Operator Nights', 'A sponsored evening series that mixes founders, operators and investors in roughly equal parts. It works well for hiring your first VP or finding your next angel.', 'Venue shared on registration', NULL, NULL, 'Founder & VC Mixers', '2026-12-03', '18:00', '$25', 'https://www.garysguide.com/events/o0kdll6/The-Builder-Series-Founder-Investor-Operator-Nights', 2),
('11111111-0000-0000-0000-000000000001', 'NachoTuesday Founder & VC Holiday Happy Hour', 'The NachoTuesday community holds its annual holiday happy hour for founders and VCs. It is the most relaxed room of December and possibly the best-connected one.', 'Venue shared on registration', NULL, NULL, 'Founder & VC Mixers', '2026-12-08', '17:00', 'Free', 'https://www.garysguide.com/events/0l1buvs/NachoTuesday-Founder-VC-Holiday-Happy-Hour', 2),
('11111111-0000-0000-0000-000000000001', 'The Deployment Room Mixer: 6 Active Funds', 'Six funds that are actively deploying from Seed to Series A+ meet founders in one room. Every investor here is writing cheques this quarter. Bring your deck on your phone.', 'Venue shared on registration', NULL, NULL, 'Founder & VC Mixers', '2027-01-21', '18:00', 'Free', 'https://www.garysguide.com/events/qat3hz5/The-Deployment-Room-Mixer-6-Active-Funds-Funding-Founders-Seed-to-Series-A-Jan-21st', 4),
('11111111-0000-0000-0000-000000000001', 'The Shortlist Founder Showcase', 'The Shortlist and Oak HC/FT present a founder showcase at Betaworks in the Meatpacking District. A curated batch of startups demos to a room of investors, with drinks afterwards.', 'Betaworks', '29 Little W 12th St', 'Meatpacking District', 'Pitch Nights & Demo Days', '2026-11-10', '18:00', 'Free', 'https://www.garysguide.com/events/yb7dz73/The-Shortlist-Founder-Showcase', 3),
('11111111-0000-0000-0000-000000000001', 'Startup Pitch: 5 Founders On Stage', 'Five founders get five minutes each in the back room of American Whiskey, with investor Q&A after every pitch. The pitches are short and the drinks are strong.', 'American Whiskey', '247 W 30th St', 'Chelsea', 'Pitch Nights & Demo Days', '2026-11-11', '18:00', '$18', 'https://www.garysguide.com/events/5m84wkz/Startup-Pitch-5-Founders-On-Stage', 2),
('11111111-0000-0000-0000-000000000001', 'Pitch Roast Live', 'Founders pitch and a panel of investors roasts them, live on stage at Caveat. It is part comedy night and part investor feedback, and it is the most honest feedback in the city.', 'Caveat', '21A Clinton St', 'Lower East Side', 'Pitch Nights & Demo Days', '2026-11-18', '18:30', 'Free', 'https://www.garysguide.com/events/z5asmih/Pitch-Roast-Live', 3),
('11111111-0000-0000-0000-000000000001', 'The Startup Pitch: Demo Showcase', 'Startup Grind NYC runs a demo showcase at The Yard on Herald Square. Founders demo live, investors judge, and the networking runs until the venue closes.', 'The Yard: Herald Square', '106 W 32nd St', 'Midtown', 'Pitch Nights & Demo Days', '2026-11-19', '17:30', '$5', 'https://www.garysguide.com/events/nszorua/The-Startup-Pitch-Demo-Showcase', 2),
('11111111-0000-0000-0000-000000000001', 'Entrepreneurs Roundtable 220', 'This is the 220th edition of New Yorks longest-running startup event series, which has run since 2007. Founders present, VCs respond, and it is hosted by Looking Glass Capital.', 'Venue shared on registration', NULL, NULL, 'Pitch Nights & Demo Days', '2026-12-01', '18:00', 'Free', 'https://www.garysguide.com/events/gysobg1/Entrepreneurs-Roundtable-220', 2),
('11111111-0000-0000-0000-000000000001', 'Startup Pitch Mixer at Whiskey Cellar', 'Startup Valleys East Village pitch night in a candlelit basement bar. Founders pitch angels and VC partners live, then everyone moves on to the open-networking part of the evening.', 'Whiskey Cellar', '77 E 7th St', 'East Village', 'Pitch Nights & Demo Days', '2026-12-02', '18:00', '$22', 'https://www.garysguide.com/events/80i32hs/Startup-Pitch-Mixer', 2),
('11111111-0000-0000-0000-000000000001', 'Startup Pitch Mixer: Holiday Edition', 'The last Startup Valley pitch night of the year at Whiskey Cellar. It is your final chance to get in front of angels before the January rush.', 'Whiskey Cellar', '77 E 7th St', 'East Village', 'Pitch Nights & Demo Days', '2026-12-16', '18:00', '$22', 'https://www.garysguide.com/events/70rz8rh/Startup-Pitch-Mixer', 2),
('11111111-0000-0000-0000-000000000001', 'Family Office Room Dinner', 'A seated dinner at Fushimi Times Square that puts founders across the table from family-office principals. The capital here is patient. Dress for a private bank, not a pitch night.', 'Fushimi Times Square', '311 W 43rd St', 'Hells Kitchen', 'Dinners & Breakfasts', '2026-11-12', '18:00', '$150', 'https://www.garysguide.com/events/oiyl845/Family-Office-Room-Dinner', 4),
('11111111-0000-0000-0000-000000000001', 'Seed to Series B Founder & Investor Townhouse Luncheon', 'A Sunday lunch in a private townhouse. Partners from 434 VC, ZERON Ventures, F&G Capital, LMT Partners and AG VC sit with founders raising from Seed through Series B.', 'Private townhouse', NULL, NULL, 'Dinners & Breakfasts', '2026-11-15', '13:30', '$250', 'https://www.garysguide.com/events/r6gkhhd/Seed-To-Series-B-Founder-Investor-Townhouse-Luncheon', 5),
('11111111-0000-0000-0000-000000000001', 'NYC Coffee Club: Early-Stage B2B Founders & Funders', 'Forum Ventures hosts a morning coffee for early-stage B2B founders and the funds that specialise in them. Breakfast hours suit people who mean business.', 'Venue shared on registration', NULL, NULL, 'Dinners & Breakfasts', '2026-11-20', '10:00', 'Free', 'https://www.garysguide.com/events/3308owv/NYC-Coffee-Club-Early-Stage-B2B-Founders-Funders', 3),
('11111111-0000-0000-0000-000000000001', 'Junto Founder Dinner', 'Andrew Yeungs Junto dinner at a private dinner club. The address arrives only after you are accepted, and the seating plan is curated. It is the founder dinner people talk about the next morning.', 'Private dinner club', NULL, NULL, 'Dinners & Breakfasts', '2026-12-09', '18:00', 'Free (application)', 'https://www.garysguide.com/events/9awr3fi/Junto-Founder-Dinner-Hosted-by-Andrew-Friends', 5),
('11111111-0000-0000-0000-000000000001', 'Founder VC Dinner with Oppenheimer & Co', 'Oppenheimer & Co hosts founders and venture investors for an early-evening dinner. It is a banker-hosted room, so the conversation is about capital.', 'Oppenheimer & Co', NULL, 'Midtown', 'Dinners & Breakfasts', '2026-12-10', '17:00', 'Free', 'https://www.garysguide.com/events/m5wvgrl/Founder-VC-Dinner', 4),
('11111111-0000-0000-0000-000000000001', 'Asian Tech Week 2026', 'A community-led week, Nov 16 to 20, of founder, investor and operator events across the city. It is one of the busiest networking weeks on the late-autumn calendar.', 'Various venues', NULL, NULL, 'Summits & Investor Days', '2026-11-16', '09:00', 'Free', 'https://www.garysguide.com/events/hk2c5vl/Asian-Tech-Week-Nov-16-20', 2),
('11111111-0000-0000-0000-000000000001', 'Independent Sponsors & Capital Providers Dealmakers', 'A full-day dealmaking forum at CohnReznick that brings independent sponsors and the capital providers behind them together. It is private-markets heavy and has serious ticket prices.', 'CohnReznick', '1301 Avenue of the Americas, 10th Fl', 'Midtown', 'Summits & Investor Days', '2026-12-09', '08:00', '$649', 'https://www.garysguide.com/events/gagcv1o/Independent-Sponsors-Capital-Providers-Dealmakers', 5),
