('11111111-0000-0000-0000-000000000001', 'AI Hackathon: Hack The Unreachable', 'A daylong AI hackathon at Fordhams Gabelli School of Business, across from Lincoln Center. Builders, MBAs and judges share one room.', 'Fordham Gabelli School of Business', '140 W 62nd St', 'Lincoln Square', 'Hackathons', '2026-11-14', '10:00', 'Free', 'https://www.garysguide.com/events/uu5hbi5/AI-Hackathon-Hack-The-Unreachable', 3),
('11111111-0000-0000-0000-000000000001', 'Money Talks: AI & Finance Hackathon', 'Block Convey hosts a fintech-meets-AI hackathon. Expect agents that trade, reconcile and underwrite, judged by people who do those jobs for a living.', 'Venue shared on registration', NULL, NULL, 'Hackathons', '2026-11-21', '09:00', 'Free', 'https://www.garysguide.com/events/vo9l7lc/Money-Talks-AI-Finance-Hackathon', 3),
